B.Fr=s([u.r,u.o,"CREATE TRIGGER booking_no_overlap_insert BEFORE INSERT ON bookings WHEN NEW.status IN ('pending', 'confirmed', 'checkedIn', 'completed') BEGIN   SELECT RAISE(ABORT, 'booking_overlap') WHERE EXISTS (\n    SELECT 1 FROM bookings b\n    WHERE b.court_id = NEW.court_id AND b.id <> NEW.id\n      AND b.status IN ('pending', 'confirmed', 'checkedIn', 'completed')\n      AND julianday(b.start_at) < julianday(NEW.end_at)\n      AND julianday(NEW.start_at) < julianday(b.end_at)\n      AND (b.part = 'full' OR NEW.part = 'full' OR b.part = NEW.part)\n  ); END","CREATE TRIGGER booking_no_overlap_update BEFORE UPDATE OF court_id, start_at, end_at, status, part ON bookings WHEN NEW.status IN ('pending', 'confirmed', 'checkedIn', 'completed') BEGIN   SELECT RAISE(ABORT, 'booking_overlap') WHERE EXISTS (\n    SELECT 1 FROM bookings b\n    WHERE b.court_id = NEW.court_id AND b.id <> NEW.id\n      AND b.status IN ('pending', 'confirmed', 'checkedIn', 'completed')\n      AND julianday(b.start_at) < julianday(NEW.end_at)\n      AND julianday(NEW.start_at) < julianday(b.end_at)\n      AND (b.part = 'full' OR NEW.part = 'full' OR b.part = NEW.part)\n  ); END","CREATE INDEX IF NOT EXISTS receipt_lines_receipt ON stock_receipt_lines (receipt_id)","CREATE INDEX IF NOT EXISTS expenses_spent ON expenses (spent_at)","CREATE INDEX IF NOT EXISTS stock_kind_time ON stock_movements (kind, created_at)"],t.s)
