B.HG=s(["CREATE UNIQUE INDEX customer_phone_unique ON customers (phone) WHERE phone IS NOT NULL AND deleted_at IS NULL","CREATE INDEX ledger_customer ON customer_ledger (customer_id)","CREATE INDEX bookings_court_time ON bookings (court_id, start_at)","CREATE INDEX bookings_customer ON bookings (customer_id)","CREATE INDEX blocked_court_time ON blocked_slots (court_id, start_at)","CREATE INDEX orders_booking ON orders (booking_id)","CREATE INDEX orders_customer ON orders (customer_id)","CREATE TRIGGER booking_no_overlap_insert BEFORE INSERT ON bookings WHEN NEW.status IN ('pending', 'confirmed', 'checkedIn', 'completed') BEGIN   SELECT RAISE(ABORT, 'booking_overlap') WHERE EXISTS (\n    SELECT 1 FROM bookings b\n    WHERE b.court_id = NEW.court_id AND b.id <> NEW.id\n      AND b.status IN ('pending', 'confirmed', 'checkedIn', 'completed')\n      AND julianday(b.start_at) < julianday(NEW.end_at)\n      AND julianday(NEW.start_at) < julianday(b.end_at)\n  ); END","CREATE TRIGGER booking_no_overlap_update BEFORE UPDATE OF court_id, start_at, end_at, status ON bookings WHEN NEW.status IN ('pending', 'confirmed', 'checkedIn', 'completed') BEGIN   SELECT RAISE(ABORT, 'booking_overlap') WHERE EXISTS (\n    SELECT 1 FROM bookings b\n    WHERE b.court_id = NEW.court_id AND b.id <> NEW.id\n      AND b.status IN ('pending', 'confirmed', 'checkedIn', 'completed')\n      AND julianday(b.start_at) < julianday(NEW.end_at)\n      AND julianday(NEW.start_at) < julianday(b.end_at)\n  ); END"],t.s)
